te-space:nowrap}\n.tag.ok{color:var(--ink);border-color:var(--accent-alt)}\n.evb{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px;text-align:left;padding:5px 6px 5px 0;border:0;background:transparent;color:var(--ink);cursor:pointer}\n.evb.static{padding-left:8px;cursor:default}\n.chk{flex:none;align-self:center;width:26px;height:26px;margin-left:4px;padding:0;border-radius:8px;border:1.5px solid var(--accent);background:transparent;color:var(--on-accent);font-size:14px;line-height:1;cursor:pointer;display:grid;place-items:center}\n.chk.on{background:var(--accent)}\n.chk.done{border-color:var(--accent-alt);color:var(--ink);cursor:default}\n.warn{display:flex;align-items:center;font-size:11px;font-weight:600}\n.wi{display:inline-grid;place-items:center;flex:none;width:13px;height:13px;margin-right:4px;border-radius:50%;background:var(--accent-alt);color:var(--on-accent);font-size:10px;font-style:normal;font-weight:700;line-height:1}\n.note{flex:none;display:flex;align-items:flex-start;justify-content:space-between;gap:6px;padding:5px 8px;border-radius:9px;background:var(--soft);color:var(--ink);font-size:11px}\n.note span{min-width:0}\n.note.flat{display:block}\n.x{flex:none;width:20px;height:20px;padding:0;border:0;border-radius:6px;background:transparent;color:var(--muted);font-size:14px;line-height:1;cursor:pointer}\n.x.ph{cursor:default}\n\n.inp{width:100%;min-width:0;padding:5px 7px;border-radius:8px;border:1px solid var(--line);background:var(--paper);color:var(--ink)}\n.arow{flex:none;display:flex;flex-direction:column;gap:3px;padding:5px 7px;border-radius:10px;border:1px solid var(--line);background:var(--panel-paper)}\n.arow.today{border-color:var(--accent)}\n.alb{display:flex;align-items:center;gap:6px;min-width:0}\n.alb .dn{font-weight:700}\n.alb small{color:var(--muted);font-size:11px}\n.alb .x{margin-left:auto}\n.ain{display:grid;grid-template-columns:minmax(0,1fr) 10px minmax(0,1fr);align-items:center;gap:3px}\n.dash{text-align:center;color:var(--muted)}\n.ain .inp{padding:3px 4px}\n.fm{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.fh{flex:none;display:flex;align-items:center;gap:6px;font-weight:700;font-size:13px;min-width:0}\n.ft{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.fbody{flex:1;min-height:0;min-width:0;overflow:auto;display:grid;grid-template-columns:minmax(0,1fr);align-content:start;gap:6px;padding-right:2px}\n.fbody.one{display:flex;flex-direction:column}\n.fld{display:grid;gap:2px;min-width:0}\n.lb{color:var(--muted);font-size:11px}\n.hint{flex:none;color:var(--muted);font-size:11px}\n.err{flex:none;display:flex;align-items:center;font-size:11.5px;font-weight:700}\n.err.sm{font-size:10.5px}\n.card[data-size=\"3x3\"]{padding:6px;gap:4px}\n.card[data-size=\"3x3\"] .wp,.card[data-size=\"3x3\"] .body,.card[data-size=\"3x3\"] .scroll{gap:4px}\n.card[data-size=\"3x3\"] .rail{gap:4px}\n.card[data-size=\"3x3\"] .tab{padding:3px 0}\n.card[data-size=\"3x3\"] .row{padding:4px 7px}\n.card[data-size=\"3x3\"] .btn{padding:5px 6px}\n.card[data-size=\"3x3\"] .fbody{gap:4px}\n.card[data-size=\"3x3\"] .inp{padding:4px 6px}\n.card[data-size=\"3x3\"] .hint{display:none}\n.card[data-size=\"6x3\"] .wp{flex-direction:row;gap:8px}\n.card[data-size=\"6x3\"] .rail{width:104px;gap:6px}\n.card[data-size=\"6x3\"] .head{flex-direction:column;align-items:stretch;gap:4px}\n.card[data-size=\"6x3\"] .wk{justify-content:space-between}\n.card[data-size=\"6x3\"] .ic{width:20px}\n.card[data-size=\"6x3\"] .wl{padding:3px 0;font-size:10.5px}\n.card[data-size=\"6x3\"] .tabs{flex-direction:column}\n.card[data-size=\"6x3\"] .tab{padding:5px 0}\n.card[data-size=\"6x3\"] .body{min-width:0}\n.card[data-size=\"6x3\"] .fbody,.card[data-size=\"6x6\"] .fbody{grid-template-columns:repeat(2,minmax(0,1fr))}\n.card[data-size=\"6x3\"] .fbody.one,.card[data-size=\"6x6\"] .fbody.one{display:flex}\n.fld.wide{grid-column:1/-1}\n.card[data-size=\"6x3\"] .arow{flex-direction:row;align-items:center;gap:8px}\n.card[data-size=\"6x3\"] .alb{width:86px;flex:none}\n.card[data-size=\"6x3\"] .ain{flex:1;min-width:0}\n.card[data-size=\"6x3\"] .arow,.card[data-size=\"6x6\"] .arow{flex-wrap:wrap}\n.arow .err{flex-basis:100%}\n.card[data-size=\"6x6\"]{padding:10px;gap:8px;font-size:13px}\n.card[data-size=\"6x6\"] .wp{gap:8px}\n.card[data-size=\"6x6\"] .groups{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 10px;align-items:start}\n.card[data-size=\"6x6\"] .arow{flex-direction:row;align-items:center;gap:10px}\n.card[data-size=\"6x6\"] .alb{width:110px;flex:none}\n.card[data-size=\"6x6\"] .ain{flex:1;min-width:0}\n.card[data-size=\"6x6\"] .tab{padding:6px 0}\n.card[data-size=\"6x6\"] .row{padding:8px 10px}\n.card[data-size=\"6x6\"] .btn{padding:8px 10px}\n";
var DAYN=['周一','周二','周三','周四','周五','周六','周日'];
var PRIO={1:'高',2:'中',3:'低'};
function p2(n){return n<10?'0'+n:''+n}
function pd(s){var a=String(s).split('-');return new Date(+a[0],+a[1]-1,+a[2])}
function fd(d){return d.getFullYear()+'-'+p2(d.getMonth()+1)+'-'+p2(d.getDate())}
function addD(s,n){var d=pd(s);d.setDate(d.getDate()+n);return fd(d)}
function wdi(s){return (pd(s).getDay()+6)%7}
function monOf(s){return addD(s,-wdi(s))}
function md(s){var a=String(s).split('-');return (+a[1])+'/'+(+a[2])}
function tm(t){var a=String(t||'').split(':');if(a.length<2||a[0]===''||a[1]==='')return NaN;return (+a[0])*60+(+a[1])}
function ft(m){return p2(Math.floor(m/60))+':'+p2(m%60)}
function fm(m){m=Math.round(m||0);if(m<60)return m+'分';var h=Math.floor(m/60),r=m%60;return h+'小时'+(r?r+'分':'')}
function okT(a,b){var s=tm(a),e=tm(b);return !isNaN(s)&&!isNaN(e)&&e>s}
function cmpEv(a,b){if(a.date!==b.date)return a.date<b.date?-1:1;return tm(a.start)-tm(b.start)}

function norm(s){
  s=s||{};
  return Object.assign({},s,{
    tasks:Array.isArray(s.tasks)?s.tasks:[],
    meetings:Array.isArray(s.meetings)?s.meetings:[],
    avail:s.avail&&typeof s.avail==='object'?s.avail:{},
    plans:s.plans&&typeof s.plans==='object'?s.plans:{}
  });
}
function mapPlans(plans,fn){
  var out={};
  Object.keys(plans).forEach(function(k){
    var p=plans[k];
    out[k]=Object.assign({},p,{items:fn(p.items||[])});
  });
  return out;
}

function busyOf(S,ws){
  var out=[];
  S.meetings.forEach(function(m){
    if(okT(m.start,m.end))out.push({date:m.date,s:tm(m.start),e:tm(m.end)});
  });
  var p=S.plans[ws];
  if(p)(p.items||[]).forEach(function(it){
    if(it.status==='confirmed'&&okT(it.start,it.end))out.push({date:it.date,s:tm(it.start),e:tm(it.end)});
  });
  return out;
}

function freeSlots(S,ws,today,nowMin){
  var busy=busyOf(S,ws),slots=[];
  for(var i=0;i<7;i++){
    var date=addD(ws,i);
    if(date<today)continue;
    var a=S.avail[i]||{};
    if(!okT(a.start,a.end))continue;
    var s=tm(a.start),e=tm(a.end);
    if(date===today){var c=Math.ceil(nowMin/15)*15;if(c>s)s=c}
    if(e-s<15)continue;
    var segs=[[s,e]];
    busy.filter(function(b){return b.date===date}).forEach(function(b){
      var nx=[];
      segs.forEach(function(g){
        if(b.e<=g[0]||b.s>=g[1]){nx.push(g);return}
        if(b.s>g[0])nx.push([g[0],b.s]);
        if(b.e<g[1])nx.push([b.e,g[1]]);
      });
      segs=nx;
    });
    segs.forEach(function(g){if(g[1]-g[0]>=15)slots.push({date:date,s:g[0],e:g[1]})});
  }
  return slots;
}


function confirmedMin(S,taskId){
  var t=0;
  Object.keys(S.plans).forEach(function(k){
    (S.plans[k].items||[]).forEach(function(it){
      if(it.taskId===taskId&&it.status==='confirmed'&&okT(it.start,it.end))t+=tm(it.end)-tm(it.start);
    });
  });
  return t;
}

// 只生成草稿；已确认的安排原样保留并当作占用时间，会议只读不动
function makePlan(S,ws,today,nowMin,newId){
  var old=S.plans[ws]||{items:[]};
  var kept=(old.items||[]).filter(function(it){return it.status==='confirmed'});
  var plans=Object.assign({},S.plans);
  plans[ws]={items:kept};
  var T=Object.assign({},S,{plans:plans});
  var slots=freeSlots(T,ws,today,nowMin);
  var q=S.tasks.map(function(t){return {t:t,r:(+t.minutes||0)-confirmedMin(S,t.id)}})
    .filter(function(x){return x.r>0});
  q.sort(function(a,b){
    var da=a.t.due||'9999',db=b.t.due||'9999';
    if(da!==db)return da<db?-1:1;
    var pa=a.t.prio||2,pb=b.t.prio||2;
    if(pa!==pb)return pa-pb;
    return b.r-a.r;
  });
  var items=[],un=[];
  q.forEach(function(x){
    var r=x.r,due=x.t.due||'';
    for(var i=0;i<slots.length&&r>0;i++){
      var sl=slots[i];
      if(due&&sl.date>due)break;
      while(r>0&&sl.e-sl.s>=15){
        var c=Math.min(r,120,sl.e-sl.s);
        if(c<r&&c<30)break;
        items.push({id:newId(),taskId:x.t.id,title:x.t.title,date:sl.date,start:ft(sl.s),end:ft(sl.s+c),sel:true,status:'draft'});
        sl.s+=c;r-=c;
        if(r>0)sl.s+=10;
      }
    }
    if(r>0)un.push({taskId:x.t.id,title:x.t.title,minutes:r,why:due?'截止日前空闲不够':'这一周空闲不够'});
  });
  return {items:kept.concat(items).sort(cmpEv),unplaced:un};
}

function conflictsOf(S,ws,it){
  if(!okT(it.start,it.end))return ['时间无效'];
  var out=[],s=tm(it.start),e=tm(it.end);
  S.meetings.forEach(function(m){
    if(m.date===it.date&&okT(m.start,m.end)&&tm(m.start)<e&&tm(m.end)>s)out.push('与会议「'+(m.title||'会议')+'」重叠');
  });
  var p=S.plans[ws];
  if(p)(p.items||[]).forEach(function(o){
    if(o.id!==it.id&&o.date===it.date&&tm(o.start)<e&&tm(o.end)>s)out.push('与「'+o.title+'」重叠');
  });
  var a=S.avail[wdi(it.date)]||{};
  if(!(okT(a.start,a.end)&&tm(a.start)<=s&&tm(a.end)>=e))out.push('不在当天空闲时段内');
  return out;
}


function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day}=ctx;
  const S=norm(state),today=day(),nd=new Date(),nowMin=nd.getHours()*60+nd.getMinutes();
  if(!ui.view)ui.view='tasks';
  if(!ui.ws)ui.ws=monOf(today);
  const ws=ui.ws,wEnd=addD(ws,6);
  const K=a=>a.filter(Boolean);
  const nui=x=>Object.assign({view:ui.view,ws:ui.ws,form:null,confirm:false,notice:'',regen:false,calMsg:false},x||{});
  const fail=()=>{ui.notice='保存失败，请重试';redraw()};
  const save=fn=>update(s=>fn(norm(s))).catch(fail);
  const go=v=>{ui.view=v;ui.regen=false;ui.notice='';redraw()};
  const btn=(label,cls,fn,dis)=>el('button',{type:'button',class:'btn'+(cls?' '+cls:''),disabled:!!dis,onclick:fn},label);
  const planUpd=fn=>s=>{
    s=norm(s);
    const p=s.plans[ws]||{items:[],unplaced:[]};
    const plans=Object.assign({},s.plans);
    plans[ws]=Object.assign({},p,{items:fn(p.items||[])});
    s.plans=plans;
    return s;
  };
  const openForm=(kind,id,draft,extra)=>{ui.form=Object.assign({kind:kind,id:id||'',draft:draft,err:''},extra||{});redraw()};
  const closeForm=()=>{ui.form=null;redraw()};

  const FD={
    task:{
      title:f=>f.id?'编辑待办':'添加待办',
      fields:[
        ['title','事项','text',{ph:'例如：写周报',wide:1}],
        ['minutes','预计用时（分钟）','number',{min:5,step:5}],
        ['prio','优先级','select',{opts:[['1','高'],['2','中'],['3','低']]}],
        ['due','截止日期（可选）','date',{}]
      ],
      save:(d,f)=>{
        const title=String(d.title||'').trim(),m=Math.round(Number(d.minutes));
        if(!title)return '请填写事项';
        if(!(m>=5))return '预计用时至少 5 分钟';
        const id=f.id||uid();
        const rec={id:id,title:title,minutes:m,due:d.due||'',prio:Number(d.prio)||2};
        return commit(s=>{
          s=norm(s);
          s.tasks=s.tasks.some(t=>t.id===id)?s.tasks.map(t=>t.id===id?Object.assign({},t,rec):t):s.tasks.concat([rec]);
          return s;
        },nui());
      },
      del:f=>commit(s=>{
        s=norm(s);
        s.tasks=s.tasks.filter(t=>t.id!==f.id);
        s.plans=mapPlans(s.plans,items=>items.filter(i=>!(i.taskId===f.id&&i.status!=='confirmed')));
        return s;
      },nui())
    },
    meet:{
      title:f=>f.id?'编辑会议记录':'录入已有会议',
      hint:'只是本卡片里的参照，用来避让；不会修改你日历里的会议。',
      fields:[
        ['title','会议名称（可空）','text',{ph:'例如：周会',wide:1}],
        ['date','日期','date',{}],
        ['start','开始','time',{}],
        ['end','结束','time',{}]
      ],
      save:(d,f)=>{
        if(!d.date)return '请选择日期';
        if(!okT(d.start,d.end))return '请填写开始和结束时间，结束需晚于开始';
        const id=f.id||uid();
        const rec={id:id,title:String(d.title||'').trim()||'会议',date:d.date,start:d.start,end:d.end};
        return commit(s=>{
          s=norm(s);
          s.meetings=s.meetings.some(m=>m.id===id)?s.meetings.map(m=>m.id===id?rec:m):s.meetings.concat([rec]);
          return s;
        },nui());
      },
      del:f=>commit(s=>{s=norm(s);s.meetings=s.meetings.filter(m=>m.id!==f.id);return s},nui())
    },
    item:{
      title:f=>'调整这条安排',
      hint:'只改本卡片里的草稿；确认后才算数。已确认的修改后会回到草稿。',
      fields:[
        ['title','内容','text',{wide:1}],
        ['date','日期','date',{min:f=>f.ws,max:f=>addD(f.ws,6)}],
        ['start','开始','time',{}],
        ['end','结束','time',{}]
      ],
      save:(d,f)=>{
        const title=String(d.title||'').trim();
        if(!title)return '请填写内容';
        if(!d.date||d.date<f.ws||d.date>addD(f.ws,6))return '日期需在这一周内';
        if(!okT(d.start,d.end))return '请填写开始和结束时间，结束需晚于开始';
        return commit(s=>{
          s=norm(s);
